package com.mo.economy_system.common.territory;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.util.concurrent.atomic.*;import org.junit.jupiter.api.Test;
class TerritoryInviteDecisionServiceTest {private record F(TerritoryInviteStore s,TerritoryInvite i){}private static F f(){TerritoryInviteStore s=new TerritoryInviteStore();UUID o=UUID.randomUUID(),t=UUID.randomUUID();TerritoryInvite i=new TerritoryInvite(UUID.randomUUID(),UUID.randomUUID(),o,o,t,"land","owner","target",0,10);s.put(i,0);return new F(s,i);}
 @Test void addedAndDeclinedConsumeOnce(){F f=f();AtomicInteger writes=new AtomicInteger();var d=new TerritoryInviteDecisionService(f.s,(a,b,c,e)->{writes.incrementAndGet();return TerritoryInviteDecisionService.WriteResult.ADDED;});assertEquals(TerritoryInviteDecisionService.Result.ACCEPTED,d.accept(f.i.inviteId(),f.i.targetPlayerId(),"target",1).result());assertEquals(TerritoryInviteDecisionService.Result.NOT_FOUND,d.accept(f.i.inviteId(),f.i.targetPlayerId(),"target",1).result());assertEquals(1,writes.get());F g=f();assertEquals(TerritoryInviteDecisionService.Result.DECLINED,new TerritoryInviteDecisionService(g.s,(a,b,c,e)->null).decline(g.i.inviteId(),g.i.targetPlayerId(),1).result());}
 @Test void persistFailureRetriesButUnknownIsTerminal(){F f=f();AtomicInteger n=new AtomicInteger();var d=new TerritoryInviteDecisionService(f.s,(a,b,c,e)->n.getAndIncrement()==0?TerritoryInviteDecisionService.WriteResult.PERSIST_FAILED:TerritoryInviteDecisionService.WriteResult.ADDED);assertEquals(TerritoryInviteDecisionService.Result.PERSIST_FAILED,d.accept(f.i.inviteId(),f.i.targetPlayerId(),"target",1).result());assertEquals(TerritoryInviteDecisionService.Result.ACCEPTED,d.accept(f.i.inviteId(),f.i.targetPlayerId(),"target",2).result());F g=f();var unknown=new TerritoryInviteDecisionService(g.s,(a,b,c,e)->TerritoryInviteDecisionService.WriteResult.STATE_UNKNOWN);assertEquals(TerritoryInviteDecisionService.Result.STATE_UNKNOWN,unknown.accept(g.i.inviteId(),g.i.targetPlayerId(),"target",1).result());assertEquals(TerritoryInviteDecisionService.Result.NOT_FOUND,unknown.accept(g.i.inviteId(),g.i.targetPlayerId(),"target",2).result());}
 @Test void runtimeAndNullAreUnknownErrorsEscape(){F f=f();var runtime=new TerritoryInviteDecisionService(f.s,(a,b,c,e)->{throw new IllegalStateException();});assertEquals(TerritoryInviteDecisionService.Result.STATE_UNKNOWN,runtime.accept(f.i.inviteId(),f.i.targetPlayerId(),"target",1).result());F g=f();var nul=new TerritoryInviteDecisionService(g.s,(a,b,c,e)->null);assertEquals(TerritoryInviteDecisionService.Result.STATE_UNKNOWN,nul.accept(g.i.inviteId(),g.i.targetPlayerId(),"target",1).result());F h=f();var error=new TerritoryInviteDecisionService(h.s,(a,b,c,e)->{throw new AssertionError();});assertThrows(AssertionError.class,()->error.accept(h.i.inviteId(),h.i.targetPlayerId(),"target",1));}
 @Test void nonTargetBusyAndSoleResolution(){F f=f();var d=new TerritoryInviteDecisionService(f.s,(a,b,c,e)->TerritoryInviteDecisionService.WriteResult.ADDED);assertEquals(TerritoryInviteDecisionService.Result.NOT_TARGET,d.accept(f.i.inviteId(),UUID.randomUUID(),"x",1).result());assertEquals(TerritoryInviteStore.SoleStatus.SOLE,d.resolveSole(f.i.targetPlayerId(),1).status());f.s.claim(f.i.inviteId(),f.i.targetPlayerId(),1);assertEquals(TerritoryInviteDecisionService.Result.BUSY,d.decline(f.i.inviteId(),f.i.targetPlayerId(),1).result());}}
